// Preparation only: generated bytes never stand in for acceptance of the checked-out revision.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { pathToFileURL } from 'node:url';
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
function git(root,...args){return execFileSync('git',args,{cwd:root,encoding:'utf8',maxBuffer:32*1024*1024});}
export function collectGeneration(root,source){
 if (!/^[a-f0-9]{40}$/.test(source) || git(root,'rev-parse','HEAD').trim()!==source) throw new Error('canonicalSourceMismatch');
 const sdk=JSON.parse(git(root,'show',`${source}:prismpm.lock`)).sdk_image;
 if (!/^[a-z0-9.-]+(:[0-9]{1,5})?\/[a-z0-9./_-]+@sha256:[0-9a-f]{64}$/.test(sdk)) throw new Error('canonicalInvalidSdk');
 const universal=new Set(JSON.parse(git(root,'show',`${source}:template.lock`)).policy_files.map(item=>item.path));
 const untracked=git(root,'ls-files','--others','--exclude-standard','-z').split('\0').filter(Boolean);
 if(untracked.length) throw new Error(`canonicalUnexpectedWrite: ${untracked.join(', ')}`);
 const changes=git(root,'diff','--raw','-z','--no-renames','HEAD').split('\0').filter(Boolean),files=[];
 for(let i=0;i<changes.length;i+=2){
  const [before,after,,,status]=changes[i].slice(1).split(' '),file=changes[i+1];
  const allowed=file==='CONFORMANCE.md'||file==='app/lexlean.lock'||/^app\/src\/[^\0]+\.lex\.tex$/.test(file)||/^(?:crates|xtask)\/[^\0]+\.rs$/.test(file);
  if(!allowed||universal.has(file)||status!=='M'||before!==after||!fs.lstatSync(path.join(root,file)).isFile()) throw new Error(`canonicalUnexpectedWrite: ${file}`);
  new TextDecoder('utf-8',{fatal:true}).decode(fs.readFileSync(path.join(root,file)));
  files.push(file);
 }
 const patch=git(root,'diff','--binary','--no-ext-diff','--no-renames','HEAD');
 return {patch,receipt:{schema:'foundry/canonical-generation/1',source,sdk,patchSha256:hash(patch),files,acceptance:false,
  next:'Review and apply patch, commit generated bytes, then run the existing full exact-head acceptance gates.'}};
}
if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href){
 const [command,source,out]=process.argv.slice(2);
 if(command!=='collect')throw new Error('canonicalUnexpectedWrite: expected collect');
 const result=collectGeneration('.',source);
 fs.mkdirSync(out,{recursive:true});
 fs.writeFileSync(path.join(out,'canonical.patch'),result.patch);
 fs.writeFileSync(path.join(out,'receipt.json'),JSON.stringify(result.receipt,null,2)+'\n');
}
